package dev.branched.compat;

import dev.branched.core.ResourceId;
import dev.branched.species.CompatibilityLevel;

import java.util.Objects;

/**
 * One audited feature-to-species mapping. {@code feature} is the original
 * PlacedFeature (or a configured-only feature when the original is generated by
 * code); ownership and the exact original id are always preserved.
 */
public record FeatureMapping(ResourceId feature,
                             ResourceId originalSpecies,
                             CompatibilityLevel level,
                             String notes) {
    public FeatureMapping {
        Objects.requireNonNull(feature, "feature");
        Objects.requireNonNull(originalSpecies, "originalSpecies");
        Objects.requireNonNull(level, "level");
        notes = notes == null ? "" : notes;
    }

    public boolean replaceable() {
        return level.mayReplace();
    }
}
